}
"use client";

import { useEffect, useRef, useState, type CSSProperties, type ReactNode } from "react";

/** Fades and lifts its children in the first time they scroll into view. */
export function Reveal({ children, delay = 0, className = "", as: Tag = "div" }: { children: ReactNode; delay?: number; className?: string; as?: "div" | "section" | "li" }) {
  const ref = useRef<HTMLElement>(null);
  const [shown, setShown] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      setShown(true);
      return;
    }
    const io = new IntersectionObserver(
      ([e]) => {
        if (e.isIntersecting) {
          setShown(true);
          io.disconnect();
        }
      },
      { threshold: 0.15, rootMargin: "0px 0px -40px 0px" },
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);
  return (
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    <Tag ref={ref as any} className={`reveal ${shown ? "in" : ""} ${className}`} style={{ transitionDelay: `${delay}ms` } as CSSProperties}>
      {children}
    </Tag>
  );
}

/** True once the element has been on screen (for one-shot sequences). */
export function useInView<T extends HTMLElement>(threshold = 0.3) {
  const ref = useRef<T>(null);
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(([e]) => e.isIntersecting && (setInView(true), io.disconnect()), { threshold });
    io.observe(el);
    return () => io.disconnect();
  }, [threshold]);
  return [ref, inView] as const;
}

/** Window scroll position, throttled to animation frames (0 when reduced motion is on). */
export function useScrollY() {
  const [y, setY] = useState(0);
  useEffect(() => {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    let raf = 0;
    const on = () => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => setY(window.scrollY));
    };
    window.addEventListener("scroll", on, { passive: true });
    return () => {
      window.removeEventListener("scroll", on);
      cancelAnimationFrame(raf);
    };
  }, []);
  return y;
}
"use client";

import { useRef, useState } from "react";

/** Full-quality master hosted outside the repo (e.g. an R2 bucket); falls back to the copy in /public. */
const REMOTE =
  process.env.NEXT_PUBLIC_HERO_VIDEO_URL ||
  "https://pub-322f2127ed23420ebefb3a5062774ae4.r2.dev/films/nightly-master-1080p60.mp4";

/** The Nightly explainer: plays muted on loop; one click restarts it with sound. */
export default function HeroVideo() {
  const ref = useRef<HTMLVideoElement>(null);
  const [sound, setSound] = useState(false);
  const toggle = () => {
    const v = ref.current;
    if (!v) return;
    if (!sound) {
      v.muted = false;
      v.currentTime = 0;
      v.play().catch(() => {});
    } else {
      v.muted = true;
    }
    setSound(!sound);
  };
  return (
    <div className="relative overflow-hidden rounded-2xl border border-line bg-[#8e8ad6] shadow-soft">
      <video
        ref={ref}
        className="block aspect-video w-full"
        poster="/video/nightly-poster.jpg"
        autoPlay
        muted
        loop
        playsInline
        preload="metadata"
        aria-label="Nightly explainer: a ghost that watches your AI agents at night"
      >
        {REMOTE && <source src={REMOTE} type="video/mp4" />}
        <source src="/video/nightly.webm" type="video/webm" />
        <source src="/video/nightly.mp4" type="video/mp4" />
      </video>
      <button
        onClick={toggle}
        className="absolute bottom-4 right-4 inline-flex items-center gap-2 rounded-full px-4 py-2 text-[13px] font-medium text-fg shadow-soft transition"
        style={{ background: "rgba(255,255,255,0.95)" }}
      >
        {sound ? "🔇 Mute" : "🔊 Play with sound"}
      </button>
    </div>
  );
}
"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { Moon } from "./ui";

const LINKS = [
  { href: "/#how", label: "How it works" },
  { href: "/sandbox", label: "Sandbox" },
  { href: "/benchmark", label: "Benchmark" },
  { href: "/business", label: "Business" },
  { href: "/judge", label: "For judges" },
];

/** Floating pill nav: flat at the top of the page, lifts into a card once you scroll. */
export default function Nav() {
  const [scrolled, setScrolled] = useState(false);
  useEffect(() => {
    const on = () => setScrolled(window.scrollY > 24);
    on();
    window.addEventListener("scroll", on, { passive: true });
    return () => window.removeEventListener("scroll", on);
  }, []);
  return (
    <div className="sticky top-0 z-40 px-3 pt-3">
      <header
        className={`mx-auto flex w-full items-center justify-between rounded-2xl px-3 py-2.5 transition-all duration-300 sm:px-4 ${
          scrolled ? "max-w-[1000px] border border-line bg-white/95 shadow-soft backdrop-blur" : "max-w-[1180px] border border-transparent"
        }`}
        style={scrolled ? { background: "rgba(255,255,255,0.92)" } : undefined}
      >
        <Link href="/" className="flex items-center gap-2 text-[14px] font-medium tracking-tight text-fg">
          <Moon size={30} />
          Nightly
        </Link>
        <nav className="hidden items-center gap-7 text-[14px] text-fg md:flex">
          {LINKS.map((l) => (
            <Link key={l.href} href={l.href} className="transition hover:text-muted">
              {l.label}
            </Link>
          ))}
        </nav>
        <div className="flex items-center gap-2">
          <Link href="/docs" className="rounded-lg bg-chip px-3.5 py-2 text-[14px] font-medium text-fg transition hover:bg-[#e8e7e0]">
            Docs
          </Link>
          <Link href="/app" className="rounded-lg bg-[#111] px-3.5 py-2 text-[14px] font-medium text-white transition hover:bg-[#2a2a2a]" style={{ color: "#fff" }}>
            Sign in
          </Link>
        </div>
      </header>
    </div>
  );
}
