export function Button({
  children,
  onClick,
  tone = "default",
  disabled,
  className = "",
}: {
  children: ReactNode;
  onClick?: () => void;
  tone?: "default" | "primary" | "danger" | "ok";
  disabled?: boolean;
  className?: string;
}) {
  const tones = {
    default: "border-line-strong bg-white/[0.04] text-fg hover:bg-white/[0.08]",
    primary: "border-white bg-white text-black hover:bg-white/90",
    danger: "border-alert/50 bg-alert/10 text-alert hover:bg-alert/20",
    ok: "border-ok/50 bg-ok/10 text-ok hover:bg-ok/20",
  };
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      className={`rounded-md border px-3 py-1.5 text-xs font-medium transition disabled:cursor-not-allowed disabled:opacity-40 ${tones[tone]} ${className}`}
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04), 0 8px 30px rgba(0, 0, 0, 0.06);
}

@keyframes marquee {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}

.marquee {
  animation: marquee 40s linear infinite;
}

.marquee-reverse {
  animation: marquee 48s linear infinite reverse;
}

.marquee:hover,
.marquee-reverse:hover {
  animation-play-state: paused;
}

.reveal {
  opacity: 0;
  transform: translateY(18px);
  transition: opacity 0.7s ease, transform 0.7s cubic-bezier(0.2, 0.7, 0.2, 1);
}

.reveal.in {
  opacity: 1;
  transform: none;
}

@keyframes flow {
  from { left: -24px; }
  to { left: 100%; }
}

.flow { animation: flow 1.6s linear infinite; }
.flow-reverse { animation: flow 1.6s linear infinite reverse; }

@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px); }
}

