          <div className="mt-0.5 text-[12.5px] text-[#616061]">Fix PR waiting for your approval.</div>
          <div className="mt-2.5 flex gap-2">
            <span className="rounded-md bg-[#007a5a] px-2.5 py-1 text-[12px] font-bold" style={{ color: "#fff" }}>
